-- Mexico milestone translations (ES/DE/FR)

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-cfdi', 'es', 'Modelo de compensación CFDI obligatorio (CFDI 4.0 versión actual)', 'México opera uno de los sistemas de compensación de facturación electrónica más maduros del mundo: cada factura debe ser validada y sellada digitalmente (timbrada) por un PAC autorizado antes de tener validez legal, en el formato XML CFDI 4.0.', '["Asegúrese de que la conectividad con el PAC y el mapeo de campos CFDI 4.0 (Anexo 20) estén actualizados — el RFC/nombre/Régimen Fiscal del receptor debe coincidir exactamente con los registros del SAT", "Adjunte los complementos requeridos cuando corresponda (Carta Porte para transporte de mercancías, Pagos para pagos en parcialidades, Comercio Exterior para exportaciones)", "Conserve las facturas XML y los acuses del PAC durante al menos 5 años"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-cfdi', 'de', 'Verpflichtendes CFDI-Clearing-Modell (CFDI 4.0 aktuelle Version)', 'Mexiko betreibt eines der ausgereiftesten E-Rechnungs-Clearing-Systeme der Welt: Jede Rechnung muss von einem autorisierten PAC im CFDI-4.0-XML-Format validiert und digital gestempelt (timbrado) werden, bevor sie rechtsgültig ist.', '["Stellen Sie sicher, dass die PAC-Konnektivität und das CFDI-4.0-Feld-Mapping (Anexo 20) aktuell sind — RFC/Name/Regimen Fiscal des Empfängers müssen genau mit den SAT-Aufzeichnungen übereinstimmen", "Fügen Sie erforderliche Complementos hinzu, wo zutreffend (Carta Porte für Warentransport, Pagos für Ratenzahlungen, Comercio Exterior für Exporte)", "Bewahren Sie XML-Rechnungen und PAC-Bestätigungen mindestens 5 Jahre lang auf"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-cfdi', 'fr', 'Modèle de contrôle CFDI obligatoire (CFDI 4.0 version actuelle)', 'Le Mexique exploite l''un des systèmes de contrôle de facturation électronique les plus matures au monde : chaque facture doit être validée et estampillée numériquement (timbrado) par un PAC autorisé avant d''être légalement valide, au format XML CFDI 4.0.', '["Assurez-vous que la connectivité PAC et le mappage des champs CFDI 4.0 (Anexo 20) sont à jour — le RFC/nom/régime fiscal du destinataire doit correspondre exactement aux registres du SAT", "Joignez les complementos requis le cas échéant (Carta Porte pour le transport de marchandises, Pagos pour les paiements échelonnés, Comercio Exterior pour les exportations)", "Conservez les factures XML et les accusés de réception du PAC pendant au moins 5 ans"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-cfdi40-2023', 'es', 'El CFDI 4.0 se vuelve obligatorio', 'Sustituye al CFDI 3.3, introduciendo una validación más estricta de los datos del receptor — las facturas ahora se verifican contra el registro de contribuyentes del SAT, no solo la consistencia interna del XML.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-cfdi40-2023', 'de', 'CFDI 4.0 wird verpflichtend', 'Ersetzt CFDI 3.3 und führt eine strengere Validierung der Empfängerdaten ein — Rechnungen werden nun gegen das Steuerpflichtigenregister des SAT geprüft, nicht nur auf interne XML-Konsistenz.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-cfdi40-2023', 'fr', 'Le CFDI 4.0 devient obligatoire', 'Remplace le CFDI 3.3, introduisant une validation plus stricte des données du destinataire — les factures sont désormais vérifiées par rapport au registre des contribuables du SAT, pas seulement la cohérence interne du XML.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-anexo20-2026', 'es', 'Entran en vigor los catálogos actualizados del Anexo 20', 'La actualización anual de catálogos del SAT (códigos de producto/servicio, formas de pago, regímenes fiscales, y más) entra en vigor — las facturas que usen códigos retirados serán rechazadas directamente ("rebota al timbrar") a partir de esta fecha.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-anexo20-2026', 'de', 'Aktualisierte Anexo-20-Kataloge treten in Kraft', 'Die jährliche Katalogaktualisierung des SAT (Produkt-/Dienstleistungscodes, Zahlungsmethoden, Steuerregime und mehr) geht live — Rechnungen mit ausgemusterten Codes werden ab diesem Datum direkt abgelehnt ("rebota al timbrar").', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-anexo20-2026', 'fr', 'Entrée en vigueur des catalogues Anexo 20 mis à jour', 'La mise à jour annuelle des catalogues du SAT (codes produit/service, modes de paiement, régimes fiscaux, et plus) entre en vigueur — les factures utilisant des codes retirés seront rejetées d''emblée (« rebota al timbrar ») à partir de cette date.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-reform', 'es', 'Reforma fiscal de 2026 — requisitos de autenticidad y aplicación más estrictos', 'Una reforma fiscal vigente desde enero de 2026 fortaleció las facultades de fiscalización del SAT, añadiendo controles de autenticidad más estrictos y responsabilidad penal por CFDIs falsos o simulados.', '["Mantenga evidencia que respalde la autenticidad de las transacciones — contratos, comprobantes de entrega, registros de pago — ya que el SAT puede solicitarlos en un plazo de 5 días hábiles", "Revise la documentación de defensa de CFDI y los procedimientos de cancelación dadas las nuevas disposiciones de responsabilidad penal"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-reform', 'de', 'Steuerreform 2026 — strengere Echtheitsanforderungen und Durchsetzung', 'Eine ab Januar 2026 geltende Steuerreform stärkte die Durchsetzungsbefugnisse des SAT und fügte strengere Echtheitsprüfungen sowie strafrechtliche Haftung für falsche oder simulierte CFDIs hinzu.', '["Bewahren Sie Nachweise zur Authentizität von Transaktionen auf — Verträge, Lieferbelege, Zahlungsnachweise —, da der SAT diese innerhalb von 5 Werktagen anfordern kann", "Überprüfen Sie CFDI-Verteidigungsdokumentation und Stornierungsverfahren angesichts der neuen strafrechtlichen Haftungsbestimmungen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('mx-reform', 'fr', 'Réforme fiscale 2026 — exigences d''authenticité et application plus strictes', 'Une réforme fiscale en vigueur depuis janvier 2026 a renforcé les pouvoirs d''application du SAT, ajoutant des contrôles d''authenticité plus stricts et une responsabilité pénale pour les CFDI faux ou simulés.', '["Conservez des preuves à l''appui de l''authenticité des transactions — contrats, preuves de livraison, relevés de paiement — car le SAT peut les demander sous 5 jours ouvrables", "Révisez la documentation de défense CFDI et les procédures d''annulation compte tenu des nouvelles dispositions de responsabilité pénale"]');
